import numpy as np

def problem(x: np.ndarray) -> float:
    x = np.clip(x, -5, 5)
    return float(0.2 * np.sum(x**2) + 0.1 * np.sum(np.sin(x) + np.cos(2*x)) + 0.05 * np.sum(x**3))

import numpy as np

def problem(x: np.ndarray) -> float:
    x = np.clip(x, -5, 5)
    quadratic = 2 * np.sum((x - np.array([1.0, -0.5, 2.0, -1.5]))**2)
    sinc_sum = 0.0
    for i in range(4):
        freq = 0.5 + i * 0.5
        sinc_sum += np.sin(np.pi * freq * x[i]) / (np.pi * x[i]) if x[i] != 0 else freq
    penalty = 0.01 * np.sum(x**4)
    return float(quadratic - 0.5 * sinc_sum + penalty)

import numpy as np

def problem(x: np.ndarray) -> float:
    x = np.clip(x, -5, 5)
    quadratic = 1.8 * np.sum((x - np.array([0.5, -0.2, 1.0, -0.75]))**2)
    sinc_sum = 0.0
    for i in range(4):
        freq = 0.7 + i * 0.6
        sinc_sum += np.sin(np.pi * freq * x[i]) / (np.pi * x[i]) if x[i] != 0 else freq
    penalty = 0.015 * np.sum(x**4)
    return float(quadratic - 0.55 * sinc_sum + penalty)
